import {
    BodyShort,
    Detail,
    Heading,
    HGrid,
    HStack,
    InlineMessage,
    Label,
    Link,
    Skeleton,
    VStack
} from '@navikt/ds-react';
import { useAtomValue } from 'jotai';
import type { ReactNode } from 'react';
import QueryErrorBoundary from 'src/components/QueryErrorBoundary';
import { useArbeidsoppfolging, useBaseUrls, usePersonData } from 'src/lib/clients/modiapersonoversikt-api';
import { themeAtom } from 'src/lib/state/theme';
import { PersonDataFeilendeSystemer } from 'src/lib/types/modiapersonoversikt-api';
import NavLogoWhite from 'src/svg/NavLogoWhite.svg';
import NavLogoNy from 'src/svg/navLogoNy.svg';
import { harFeilendeSystemer } from '../../utils';
import { Adresseinfo } from '../components';

const IKKE_TILGJENGELIG = 'Ikke tilgjengelig';
const STENGT = 'Stengt';
const UKJENT = 'Ukjent åpningstid';

/** Om vi mottar "Ukjent" for både åpning og stenging av Nav-kontor settes verdien til "Ukjent" */
function formaterApningstid(apningstid: string): string {
    const deler = apningstid.split('-').map((del) => del.trim());
    const alleUkjente = deler.length > 1 && deler.every((del) => del.toLowerCase() === UKJENT.toLowerCase());
    return alleUkjente ? UKJENT : apningstid;
}

function hentDagensApningstid(apningstider: { ukedag: string; apningstid: string }[]): string | null {
    if (apningstider.length === 0) return null;
    const dagensUkedag = new Date().toLocaleDateString('nb-NO', { weekday: 'long' }).toLowerCase();
    const apningstid = apningstider.find((a) => a.ukedag.toLowerCase() === dagensUkedag)?.apningstid;
    return apningstid === undefined ? STENGT : formaterApningstid(apningstid);
}

function IkkeTilgjengelig() {
    return (
        <BodyShort size="small" textColor="subtle">
            {IKKE_TILGJENGELIG}
        </BodyShort>
    );
}

function InfoFelt({ label, children }: { label: string; children: ReactNode }) {
    return (
        <VStack gap="space-4">
            <Label size="small">{label}</Label>
            {children}
        </VStack>
    );
}

function KontorLenke({ navEnhetId }: { navEnhetId: string }) {
    const { data, isLoading, error } = useBaseUrls();
    const baseUrl = data?.norg2Frontend ?? '';

    return (
        <QueryErrorBoundary loading={isLoading} error={error} loader={<Skeleton variant="text" />}>
            <Detail>
                <Link href={`${baseUrl}/#/startsok?enhetNr=${navEnhetId}`} target="_blank" rel="noopener noreferrer">
                    Flere detaljer om kontoret
                </Link>
            </Detail>
        </QueryErrorBoundary>
    );
}

function Veileder() {
    const { data } = useArbeidsoppfolging();
    const veileder = data?.oppfolging?.veileder;
    if (!veileder) return null;
    return (
        <InfoFelt label="Veileder - arbeidsoppfølging">
            <BodyShort size="small">{veileder.navn}</BodyShort>
        </InfoFelt>
    );
}

function NavKontor() {
    const { data } = usePersonData();
    const theme = useAtomValue(themeAtom);
    const person = data?.person;
    const feilendeSystemer = data?.feilendeSystemer ?? [];
    const geografiskTilknytning = person?.geografiskTilknytning;
    const navEnhet = person?.navEnhet;

    if (harFeilendeSystemer(feilendeSystemer, PersonDataFeilendeSystemer.NORG_NAVKONTOR)) {
        return (
            <VStack gap="space-16">
                <HStack justify="space-between" align="center">
                    <Heading size="small" level="2">
                        Ukjent Nav-kontor
                    </Heading>
                    {theme === 'light' ? (
                        <NavLogoNy className="h-[1.2rem] w-auto shrink-0" aria-hidden />
                    ) : (
                        <NavLogoWhite
                            viewBox="325.1 269.8 191.2 56.8"
                            className="h-[1.2rem] w-auto shrink-0"
                            aria-hidden
                        />
                    )}
                </HStack>
                <InlineMessage status="warning" size="small">
                    Feilet ved uthenting av informasjon om Nav-kontor
                </InlineMessage>
            </VStack>
        );
    }

    if (!geografiskTilknytning) {
        return null;
    }

    if (!navEnhet) {
        return (
            <VStack gap="space-16">
                <HStack justify="space-between" align="center">
                    <Heading size="small" level="2">
                        Ukjent Nav-kontor
                    </Heading>
                    {theme === 'light' ? (
                        <NavLogoNy className="h-[1.2rem] w-auto shrink-0" aria-hidden />
                    ) : (
                        <NavLogoWhite
                            viewBox="325.1 269.8 191.2 56.8"
                            className="h-[1.2rem] w-auto shrink-0"
                            aria-hidden
                        />
                    )}
                </HStack>
                <InlineMessage status="warning" size="small">
                    Fant ikke geografisk tilknytning for bruker
                </InlineMessage>
            </VStack>
        );
    }

    const forsteMottakAdresse = navEnhet.publikumsmottak.at(0)?.besoksadresse;
    const apningstider = navEnhet.publikumsmottak.at(0)?.apningstider ?? [];
    const dagensApningstid = hentDagensApningstid(apningstider);

    return (
        <VStack gap="space-24">
            <HStack justify="space-between" align="center" gap="space-8">
                <Heading size="small" level="2">
                    {navEnhet.navn}
                </Heading>
                {theme === 'light' ? (
                    <NavLogoNy className="h-[1.2rem] w-auto shrink-0" aria-hidden />
                ) : (
                    <NavLogoWhite viewBox="325.1 269.8 191.2 56.8" className="h-[1.2rem] w-auto shrink-0" aria-hidden />
                )}
            </HStack>

            <Veileder />

            <HGrid columns={{ xs: 1, sm: 2 }} gap={{ xs: 'space-16', sm: 'space-8 space-16' }} align="start">
                <InfoFelt label="Kontaktadresse">
                    {forsteMottakAdresse ? <Adresseinfo adresse={forsteMottakAdresse} /> : <IkkeTilgjengelig />}
                </InfoFelt>

                <InfoFelt label="E-post">
                    {navEnhet.epost ? (
                        <BodyShort size="small" className="break-words [overflow-wrap:anywhere]">
                            {navEnhet.epost}
                        </BodyShort>
                    ) : (
                        <IkkeTilgjengelig />
                    )}
                </InfoFelt>

                <InfoFelt label="Åpent i dag">
                    {dagensApningstid ? <BodyShort size="small">{dagensApningstid}</BodyShort> : <IkkeTilgjengelig />}
                </InfoFelt>

                <InfoFelt label="Telefonnummer">
                    {navEnhet.telefonnummer ? (
                        <BodyShort size="small">{navEnhet.telefonnummer}</BodyShort>
                    ) : (
                        <IkkeTilgjengelig />
                    )}
                </InfoFelt>
            </HGrid>

            <KontorLenke navEnhetId={navEnhet.id} />
        </VStack>
    );
}

export default NavKontor;
